    const format = document.mime==='application/pdf' ? 'PDF' : document.mime==='application/gzip' ? 'GZIP-архив' : document.mime?.startsWith('image/') ? 'Изображение' : 'Текст';
    const controls = `${edit(ctx,'documents',document.id)}${history(ctx,'documents',document.id)}${document.mime!=='application/gzip' && document.kind!=='genetic_report' ? `<button class="button button-secondary button-small" type="button" data-import-document="${esc(ctx,document.id)}">Извлечь результаты</button>` : ''}`;
    return `<article class="v2-compact-row document-row" data-document-row="${esc(ctx,document.id)}"><div class="v2-row-main"><h2 class="card-title"><button class="v2-row-title" type="button" data-document="${esc(ctx,document.id)}">${esc(ctx,document.title || document.fileName || 'Документ')}</button></h2><p class="card-copy">${esc(ctx,document.description)}</p></div><div class="v2-row-meta">${badge(ctx,DOCUMENT_KIND_LABELS[document.kind] || 'Документ')}<span>${esc(ctx,format)}${document.size ? ` · ${esc(ctx,(document.size/1024).toFixed(0))} КБ` : ''}</span><span>Дата документа: ${esc(ctx,date(ctx,document.date))}</span>${added ? `<span>Добавлено: ${esc(ctx,date(ctx,added))}</span>` : ''}${linked.length ? `<div class="v2-related">${linked.map(problem=>href(ctx,`problem/${encode(problem.id)}`,esc(ctx,problem.title),'v2-related-link')).join('')}</div>` : '<span>Без привязки к проблеме</span>'}</div>${actionMenu(controls)}</article>`;
