  const points = entries.filter(point => point.value !== null && Number.isFinite(point.time));
  if (!points.length) return empty(ctx,'Для графика нужны числовой результат и точная дата. Нечисловые значения сохранены в таблице ниже.');
  const allValues = points.flatMap(({lab,value}) => [value,...[lab.low,lab.high].filter(Number.isFinite)]), min = Math.min(...allValues), max = Math.max(...allValues), padding = (max - min || Math.max(Math.abs(max),1)) * .12, low = min - padding, high = max + padding;
  if (!Number.isFinite(low) || !Number.isFinite(high) || !Number.isFinite(high-low)) return empty(ctx,'Масштаб этих чисел нельзя корректно отобразить на графике. Исходные результаты сохранены в таблице ниже.');
  const compact = points.length <= 3, width = compact ? 360 : 760, height = compact ? 240 : 280, left = compact ? 55 : 70, right = compact ? 18 : 24, top = 24, bottom = 50, first = Math.min(...points.map(p => p.time)), last = Math.max(...points.map(p => p.time));
  const x = time => last === first ? (width + left - right)/2 : left + (time - first)/(last - first)*(width-left-right), y = value => top + (high - value)/(high-low)*(height-top-bottom);
  const n = value => Number(value).toFixed(2), format = value => new Intl.NumberFormat('ru',{maximumFractionDigits:3}).format(value);
  const titleId = 'trend-' + String(points[0].lab.id).replace(/[^a-zA-Z0-9_-]/g,'');
  const ticks = [low,(low+high)/2,high].map(value => `<line class="v2-chart-grid" x1="${left}" x2="${width-right}" y1="${n(y(value))}" y2="${n(y(value))}"/><text class="v2-chart-label" x="${left-10}" y="${n(y(value)+4)}" text-anchor="end">${esc(ctx,format(value))}</text>`).join('');
  const refs = points.filter(({lab}) => Number.isFinite(lab.low) && Number.isFinite(lab.high)).map(({lab,time}) => `<line class="v2-reference-mark" x1="${n(x(time))}" x2="${n(x(time))}" y1="${n(y(lab.low))}" y2="${n(y(lab.high))}"><title>${esc(ctx,'Референс: ' + lab.reference)}</title></line>`).join('');
  const segments = []; let segment = [];
  for (const point of entries) {
    if (point.value === null || !Number.isFinite(point.time)) { if (segment.length > 1) segments.push(segment); segment = []; }
    else segment.push(point);
  }
  if (segment.length > 1) segments.push(segment);
  const path = segments.map(part => `<polyline class="v2-trend-line" points="${part.map(point => `${n(x(point.time))},${n(y(point.value))}`).join(' ')}"/>`).join('');
  const circles = points.map(({lab,value,time}) => `<circle class="v2-trend-point" cx="${n(x(time))}" cy="${n(y(value))}" r="4.5"><title>${esc(ctx,`${date(ctx,observationDate(lab))}: ${lab.value} ${lab.unit}; референс ${lab.reference || 'не указан'}`)}</title></circle>`).join('');
  const dates = points.length === 1 ? `<text class="v2-chart-label" x="${n(x(first))}" y="${height-15}" text-anchor="middle">${esc(ctx,date(ctx,observationDate(points[0].lab)))}</text>` : `<text class="v2-chart-label" x="${left}" y="${height-15}">${esc(ctx,date(ctx,observationDate(points[0].lab)))}</text><text class="v2-chart-label" x="${width-right}" y="${height-15}" text-anchor="end">${esc(ctx,date(ctx,observationDate(points.at(-1).lab)))}</text>`;
  return `<figure class="v2-chart${compact ? ' v2-chart--compact' : ''}"><svg viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${titleId}"><title id="${titleId}">${esc(ctx,`${points[0].lab.name}: ${points.length} числовых измерений`)}</title>${ticks}${refs}${path}${circles}${dates}</svg><figcaption>${points.length === 1 ? 'Пока одно числовое измерение. Динамику оценивать рано.' : `Числовых измерений: ${points.length}.`}${points.length < series.length ? ' Остальные результаты или неточные даты показаны в таблице.' : ''} Серые отметки — референс соответствующего бланка, если его границы внесены.</figcaption></figure>`;
