  const imports = (Array.isArray(ctx.vault?.geneticImports) ? ctx.vault.geneticImports : []).filter(item=>item.personId===ctx.personId), sourceIds = new Set([...imports.flatMap(item=>item.sourceDocumentIds || []),...records.flatMap(item=>item.sourceDocumentIds || [])]);
  const reviews = all(ctx,'documents').filter(document=>document.kind==='report' && sourceIds.has(document.id));
  const focused = records.filter(record=>record.assessment && record.assessmentScope!=='general_index_context').length;
  const sectionOptions = [['','Все разделы'],...geneticSections,...[['raw','Сверка исходных данных'],['manual','Внесено вручную'],['other','Другие разделы']].filter(([key])=>records.some(record=>geneticSectionOf(record)===key))];
  const sections = records.length ? `<div class="v2-section-grid">${geneticSections.map(([key,label])=>{const count=records.filter(record=>geneticSectionOf(record)===key).length;return `<button class="v2-section-card" type="button" data-genetic-section="${key}" aria-pressed="${filters.geneticSection===key}"${!count ? ' disabled' : ''}><strong>${label}</strong><span>${count} карточек</span></button>`;}).join('')}</div>` : '';
  const coverage = geneticCoverage(ctx);
  const rows = page.items.map(record=>{
    const title=geneticDisplayTitle(record), state=geneticContentState(ctx,record);
    return `<article class="v2-compact-row genetic-row" data-genetic-row="${esc(ctx,record.id)}"><div class="v2-row-main"><h2 class="card-title">${href(ctx,`genetic/${encode(record.id)}`,esc(ctx,title))}</h2>${title!==record.title ? `<p class="section-note" lang="en">У поставщика: ${esc(ctx,record.title)}</p>` : ''}<p class="card-copy">${esc(ctx,providerResult(record))}</p></div><div class="v2-row-meta">${badge(ctx,contentLabels[state])}<span>${esc(ctx,geneticCategoryLabel(record.category || record.section || 'Другие результаты'))}</span><span>Отметка поставщика: ${esc(ctx,geneticLevels[geneticLevel(record)])}</span><p class="section-note">${geneticProvenance(ctx,record)}${record.preliminaryAsShown ? ' · результат предварительный у поставщика' : ''}</p><div class="v2-related">${linksFor(ctx,record)}</div></div>${actionMenu(`${href(ctx,`genetic/${encode(record.id)}`,'Результат и разбор','button button-secondary button-small')}${edit(ctx,'genetics',record.id)}${history(ctx,'genetics',record.id)}`)}</article>`;
  }).join('');
