  if (!record) return `${head(ctx,'ГЕНЕТИКА','Результат не найден','Выберите запись в текущем профиле.')}${href(ctx,'genetics','Все генетические результаты →','button button-secondary')}`;
  const variants = Array.isArray(record.variants) ? record.variants : [];
